const languageSwitcher = document.querySelector("#language-switcher");
const selectedLanguage = new URLSearchParams(window.location.search).get("lang") === "fr" ? "fr" : "en";
const originalTextNodes = new WeakMap();

function translateText(value) {
  const normalized = value.replace(/\s+/g, " ").trim();
  const translation = frenchTranslations[normalized];
  if (!translation) return value;
  const leading = value.match(/^\s*/)?.[0] ?? "";
  const trailing = value.match(/\s*$/)?.[0] ?? "";
  return `${leading}${translation}${trailing}`;
}

function applyLanguage(language) {
  const isFrench = language === "fr";
  document.documentElement.lang = isFrench ? "fr" : "en";
  document.title = isFrench ? (frenchAttributes[document.title] ?? document.title) : originalTitle;

  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (!originalTextNodes.has(node)) originalTextNodes.set(node, node.nodeValue);
    const original = originalTextNodes.get(node);
    node.nodeValue = isFrench ? translateText(original) : original;
  }

  for (const element of document.querySelectorAll("[alt], [placeholder], [aria-label], [title]")) {
    for (const attribute of ["alt", "placeholder", "aria-label", "title"]) {
      if (!element.hasAttribute(attribute)) continue;
      const original = element.getAttribute(`data-original-${attribute}`) ?? element.getAttribute(attribute);
      element.setAttribute(`data-original-${attribute}`, original);
      element.setAttribute(attribute, isFrench ? (frenchAttributes[original] ?? frenchTranslations[original] ?? original) : original);
    }
  }

  if (languageSwitcher) languageSwitcher.value = language;
  for (const link of document.querySelectorAll('a[href$=".html"]')) {
    const href = link.getAttribute("href");
    link.setAttribute("href", isFrench ? `${href}?lang=fr` : href);
  }
}

const originalTitle = document.title;
if (languageSwitcher) {
  languageSwitcher.value = selectedLanguage;
  languageSwitcher.addEventListener("change", () => {
    const url = new URL(window.location.href);
    if (languageSwitcher.value === "fr") url.searchParams.set("lang", "fr");
    else url.searchParams.delete("lang");
    window.location.assign(url.href);
  });
}

applyLanguage(selectedLanguage);
